<?php
declare(strict_types=1);
require_once __DIR__.'/routes.php';
function ps_enabled():bool{$c=config();$safe=parse_url($c['app_url'],PHP_URL_SCHEME)==='https'||(($c['customer_auth_test_mode']??false)===true&&in_array(parse_url($c['app_url'],PHP_URL_HOST),['127.0.0.1','localhost','::1'],true));return $safe&&($c['prospect_exchange_enabled']??false)===true&&ca_privacy_settings()['enabled'];}
function ps_gate():void{if(!ps_enabled()||crm_query("SELECT state FROM nd_schema_migrations WHERE version='018_prospect_exchange'")->fetchColumn()!=='applied')crm_fail(503,'Обмен документами закрыт до проверки документов и настройки владельцем.');}
function ps_event(int $link,string $actor,string $action,array $evidence=[]):void{crm_query('INSERT INTO nd_lc_prospect_events(link_id,actor_type,action,evidence_json) VALUES (?,?,?,?)',[$link,$actor,$action,lc_json($evidence)]);}
function ps_cookie_name():string{return parse_url(config()['app_url'],PHP_URL_SCHEME)==='https'?'__Host-nd_prospect':'nd_prospect';}
function ps_session(bool $write=false,bool $consent=true):array{
 ps_gate();$raw=$_COOKIE[ps_cookie_name()]??'';if(!is_string($raw)||!preg_match('/^[a-f0-9]{64}$/D',$raw))crm_fail(401,'Откройте действующую защищённую ссылку.');
 $s=crm_query('SELECT s.*,l.order_id,l.customer_id,l.scope_json,l.policy_version,l.policy_hash,l.expires_at AS link_expires,l.revoked_at FROM nd_lc_prospect_sessions s JOIN nd_lc_prospect_links l ON l.id=s.link_id WHERE s.token_hash=?',[hash('sha256',$raw)])->fetch();
 if(!$s||$s['revoked_at']!==null||(int)$s['expires_at']<=time()||(int)$s['link_expires']<=time())crm_fail(401,'Ссылка истекла или отозвана. Запросите новую у владельца.');$p=ca_privacy_settings();if($s['policy_version']!==$p['version']||!hash_equals($s['policy_hash'],$p['hash']))crm_fail(409,'Документы обработки данных обновлены. Нужна новая ссылка владельца.');
 if($write){same_origin();$csrf=$_SERVER['HTTP_X_CSRF_TOKEN']??'';if(!is_string($csrf)||!hash_equals($s['csrf_hash'],hash('sha256',$csrf)))crm_fail(403,'Обновите защищённую страницу.');}
 if($consent&&$s['consent_at']===null)crm_fail(403,'Прочитайте политику и отдельно подтвердите согласие.');return $s;
}
function ps_binding(array $s,int $id):array{
 $scope=json_decode($s['scope_json'],true,512,JSON_THROW_ON_ERROR);$allowed=null;foreach($scope as $item)if($item['id']===$id)$allowed=$item;
 if(!$allowed)crm_fail(404,'Документ недоступен по этой ссылке.');$b=lc_binding(['type'=>'owner','id'=>1],$id);if((int)$b['order_id']!==(int)$s['order_id']||!hash_equals($allowed['hash'],$b['generated_hash'])||!in_array($b['state'],['SENT','CLIENT_RESPONSE','SIGNED_COPY_SUBMITTED','AGREED'],true))crm_fail(404,'Документ недоступен по этой ссылке.');return $b;
}
function ps_create(array $d):array{
 ps_gate();$owner=['type'=>'owner','id'=>1];$key=bill_key($d);$order=crm_record('orders',cc_id($d['order_id']??null));$ids=$d['document_ids']??null;if(!is_array($ids)||!array_is_list($ids)||count($ids)<1||count($ids)>10||count(array_filter($ids,fn($id)=>is_int($id)&&$id>0))!==count($ids)||count(array_unique($ids,SORT_REGULAR))!==count($ids)||($d['confirm']??false)!==true)crm_fail(422,'Выберите точные документы одного заказа и подтвердите их передачу.');$hours=$d['hours']??48;if(!is_int($hours)||$hours<1||$hours>168)crm_fail(422,'Срок ссылки: от 1 до 168 часов.');$mail=($d['send_email']??false)===true;$recipient='';if($mail){ca_mail_gate();$recipient=ca_email(['email'=>crm_record('customers',(int)$order['customer_id'])['email']??'']);}
 $raw=bin2hex(random_bytes(32));$policy=ca_privacy_settings();$requestHash=hash('sha256',lc_json([$order['id'],$ids,$hours,$mail,$policy['version'],$policy['hash']]));$r=crm_atomic(function()use($d,$owner,$key,$order,$ids,$hours,$raw,$policy,$requestHash){
  crm_record('orders',(int)$order['id'],true);$old=crm_query('SELECT id,scope_json,request_hash FROM nd_lc_prospect_links WHERE request_key=?',[$key])->fetch();if($old){$oldIds=array_column(json_decode($old['scope_json'],true),'id');if($oldIds!==$ids||!hash_equals($old['request_hash'],$requestHash))crm_fail(409,'Ключ запроса уже использован для другого состава.');return ['ok'=>true,'id'=>(int)$old['id'],'replayed'=>true,'reissue_required'=>true];}
  $scope=[];foreach($ids as $id){$b=lc_binding($owner,cc_id($id),true);if((int)$b['order_id']!==(int)$order['id']||!in_array($b['kind'],['proposal','agreement','specification'],true)||!in_array($b['state'],['OWNER_REVIEW','SENT','CLIENT_RESPONSE','SIGNED_COPY_SUBMITTED','AGREED'],true))crm_fail(422,'Ссылка может включать только допустимые точные версии предложения, договора и ТЗ этого заказа.');
   if($b['state']==='OWNER_REVIEW')lc_document_action($owner,(int)$b['id'],'send',['version'=>(int)$b['version'],'checksum'=>$b['generated_hash'],'confirm'=>true,'reason'=>'Владелец проверил передачу точной версии по ограниченной ссылке.','delivery_channel'=>'scoped_link']);$scope[]=['id'=>(int)$id,'hash'=>$b['generated_hash']];}
  crm_query('INSERT INTO nd_lc_prospect_links(order_id,customer_id,token_hash,request_key,request_hash,scope_json,policy_version,policy_hash,expires_at) VALUES (?,?,?,?,?,?,?,?,?)',[$order['id'],$order['customer_id'],hash('sha256',$raw),$key,$requestHash,lc_json($scope),$policy['version'],$policy['hash'],time()+$hours*3600]);$id=(int)db()->lastInsertId();ps_event($id,'owner','link_created',['documents'=>$scope,'hours'=>$hours]);return ['ok'=>true,'id'=>$id,'replayed'=>false];
 });if($r['replayed'])return $r;$url=rtrim(config()['app_url'],'/').'/prospect.php#token='.$raw;
 if(!$mail)return $r+['url'=>$url,'delivery_confirmed'=>false,'channel'=>'owner_secure_handover'];
 $from=config()['customer_mail']['from'];$body="Владелец НейроДело подготовил документы по вашему обращению.\r\n".$url."\r\nСсылка открывает только выбранные документы и загрузку подписанной бумажной копии. Не пересылайте её третьим лицам. Она не создаёт аккаунт и не является электронной подписью.";
 $message='From: '.$from."\r\nTo: ".$recipient."\r\nSubject: =?UTF-8?B?".base64_encode('Документы НейроДело')."?=\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n".chunk_split(base64_encode($body),76,"\r\n");$ok=customer_smtp_send($recipient,$message);if(!$ok)crm_query('UPDATE nd_lc_prospect_links SET revoked_at=? WHERE id=?',[time(),$r['id']]);ps_event($r['id'],'owner',$ok?'smtp_accepted':'smtp_failed_link_revoked');return $r+['smtp_accepted'=>$ok,'delivery_confirmed'=>false,'reissue_required'=>!$ok];
}
function ps_upload(array $s):array{
 $b=ps_binding($s,cc_id(filter_var($_POST['binding_id']??'',FILTER_VALIDATE_INT)));if(!in_array($b['kind'],['agreement','specification'],true)||$b['state']==='AGREED')crm_fail(409,'Загрузка доступна для ещё не проверенной бумажной копии договора или ТЗ.');$meta=cc_validate_file($_FILES['file']??[]);if(!in_array($meta['mime'],['application/pdf','image/png','image/jpeg'],true))crm_fail(422,'Для подписанной копии разрешены PDF, JPG и PNG.');$key=bill_key(['request_key'=>$_POST['request_key']??null]);$root=cc_storage(true);$lockPath=$root.'/.quota.lock';if(is_link($lockPath))crm_fail(503,'Хранилище недоступно.');$lock=fopen($lockPath,'c');if(!$lock||!flock($lock,LOCK_EX))crm_fail(503,'Хранилище занято.');chmod($lockPath,0600);$stored=null;
 try{return crm_atomic(function()use($s,$b,$meta,$key,$root,&$stored){crm_record('orders',(int)$s['order_id'],true);$fresh=ps_session(true);$binding=ps_binding($fresh,(int)$b['id']);if($binding['state']==='AGREED')crm_fail(409,'Копия уже проверена.');$old=crm_query('SELECT * FROM nd_lc_prospect_uploads WHERE link_id=? AND request_key=?',[$s['link_id'],$key])->fetch();if($old){if((int)$old['binding_id']!==(int)$b['id']||!hash_equals($old['checksum'],$meta['checksum']))crm_fail(409,'Повтор отличается от исходной загрузки.');return ['ok'=>true,'id'=>(int)$old['id'],'replayed'=>true];}
  $used=0;foreach(new DirectoryIterator($root) as $e){if($e->isDot()||$e->getFilename()==='.quota.lock')continue;if($e->isLink()||!$e->isFile())crm_fail(503,'Хранилище требует проверки.');$used+=$e->getSize();}cc_capacity($used,$meta['size_bytes'],min(536870912,max(1,(int)(config()['collaboration_total_max_bytes']??104857600))),disk_free_space($root));
  $storage=bin2hex(random_bytes(32));$stored=$root.'/'.$storage;if(file_exists($stored)||!move_uploaded_file($_FILES['file']['tmp_name'],$stored)||!chmod($stored,0600)||hash_file('sha256',$stored)!==$meta['checksum'])crm_fail(503,'Не удалось подтвердить сохранение копии.');
  crm_query('INSERT INTO nd_lc_prospect_uploads(link_id,binding_id,storage_key,display_name,mime,size_bytes,checksum,request_key) VALUES (?,?,?,?,?,?,?,?)',[$s['link_id'],$b['id'],$storage,$meta['display_name'],$meta['mime'],$meta['size_bytes'],$meta['checksum'],$key]);$id=(int)db()->lastInsertId();ps_event((int)$s['link_id'],'prospect','paper_copy_uploaded',['upload_id'=>$id,'binding_id'=>(int)$b['id'],'checksum'=>$meta['checksum'],'identity_verified'=>false]);crm_notice('prospect-upload:'.$id,'orders',(int)$s['order_id'],'Получена бумажная копия. Нужна проверка владельцем.');return ['ok'=>true,'id'=>$id,'owner_review_required'=>true];});}catch(Throwable $e){if($stored)cc_cleanup_upload($stored);throw $e;}finally{flock($lock,LOCK_UN);fclose($lock);}
}
function ps_import(array $d):array{
 return crm_atomic(function()use($d){$u=crm_query('SELECT u.*,l.order_id FROM nd_lc_prospect_uploads u JOIN nd_lc_prospect_links l ON l.id=u.link_id WHERE u.id=? FOR UPDATE',[cc_id($d['upload_id']??null)])->fetch();if(!$u)crm_fail(404,'Копия не найдена.');if(($d['confirm']??false)!==true)crm_fail(422,'Проверьте источник и соответствие копии.');$b=lc_binding(['type'=>'owner','id'=>1],(int)$u['binding_id'],true);$path=cc_file_path($u);if($u['imported_file_id'])return ['ok'=>true,'id'=>(int)$u['imported_file_id'],'binding_id'=>(int)$b['id'],'replayed'=>true];if(!in_array($b['state'],['SENT','CLIENT_RESPONSE','SIGNED_COPY_SUBMITTED'],true))crm_fail(409,'Документ уже проверен или отозван.');
  crm_query("INSERT INTO nd_cc_files(project_id,storage_key,display_name,mime,size_bytes,checksum,actor_type,actor_id,visibility) VALUES (?,?,?,?,?,?,'owner',1,'customer')",[$b['project_id'],$u['storage_key'],$u['display_name'],$u['mime'],$u['size_bytes'],$u['checksum']]);$fid=(int)db()->lastInsertId();crm_query('UPDATE nd_lc_prospect_uploads SET imported_file_id=? WHERE id=?',[$fid,$u['id']]);ps_event((int)$u['link_id'],'owner','paper_copy_imported',['upload_id'=>(int)$u['id'],'file_id'=>$fid,'source'=>'prospect_upload','identity_verified'=>false]);lc_document_action(['type'=>'owner','id'=>1],(int)$b['id'],'signed-copy',['version'=>(int)$b['version'],'checksum'=>$b['generated_hash'],'file_id'=>$fid,'reason'=>cc_text($d,'reason',3000)]);return ['ok'=>true,'id'=>$fid,'binding_id'=>(int)$b['id'],'owner_signature_review_pending'=>true];});
}
